+use std::process::Stdio;
+use tokio::process::Command;
+use anyhow::Result;
+use crate::model::Automation;
+
+pub async fn execute_automation(automation: &mut Automation) -> Result<String> {
+    if !automation.enabled {
+        return Err(anyhow::anyhow!("Automation '{}' is disabled", automation.name));
+    }
+
+    if automation.commands.is_empty() {
+        return Err(anyhow::anyhow!("No commands to execute"));
+    }
+
+    let mut output = String::new();
+
+    for cmd in &automation.commands {
+        output.push_str(&format!("$ {} {}\n", cmd.command, cmd.args.join(" ")));
+
+        let mut command = Command::new(&cmd.command);
+        command.args(&cmd.args);
+        command.stdout(Stdio::piped());
+        command.stderr(Stdio::piped());
+
+        if let Some(dir) = &cmd.working_dir {
+            command.current_dir(dir);
+        }
+
+        let child = command.spawn()?;
+        let out = child.wait_with_output().await?;
+
+        if out.status.success() {
+            let stdout = String::from_utf8_lossy(&out.stdout);
+            if !stdout.is_empty() {
+                output.push_str(&stdout);
+            }
+            output.push_str("[OK]\n");
+        } else {
+            let stderr = String::from_utf8_lossy(&out.stderr);
+            output.push_str(&format!("[FAILED] exit code: {}\n", out.status));
+            if !stderr.is_empty() {
+                output.push_str(&stderr);
+            }
+        }
+    }
+
+    automation.last_run = Some(chrono::Utc::now());
+
+    Ok(output)
+}

