+use std::io;
+use std::sync::Arc;
+use std::time::Duration;
+use crossterm::{
+    event::{self, Event, KeyCode, KeyEventKind},
+    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
+    ExecutableCommand,
+};
+use ratatui::prelude::*;
+use anyhow::Result;
+use tokio::sync::Mutex;
+use notify::{Watcher, RecursiveMode, event::EventKind};
+
+use crate::storage::Storage;
+use crate::tui::{App, AppView, CreateField};
+use crate::triggers::{TriggerEngine, read_battery};
+use crate::model::SystemEventType;
+
+#[tokio::main]
+async fn main() -> Result<()> {
+    let storage = Storage::new()?;
+    let automations = storage.list_automations()?;
+    let automations_arc = Arc::new(Mutex::new(automations));
+    let engine_arc = Arc::new(Mutex::new(TriggerEngine::new()));
+
+    {
+        let mut engine = engine_arc.lock().await;
+        let autos = automations_arc.lock().await;
+        engine.index_automations(&autos);
+    }
+
+    let (trigger_tx, mut trigger_rx) = tokio::sync::mpsc::channel(100);
+
+    let engine_clone = engine_arc.clone();
+    let autos_clone = automations_arc.clone();
+    let trigger_tx_clone = trigger_tx.clone();
+
+    let _monitor_handle = tokio::spawn(async move {
+        let mut battery_interval = tokio::time::interval(Duration::from_secs(5));
+        let mut cron_interval = tokio::time::interval(Duration::from_secs(10));
+        let mut idle_check_interval = tokio::time::interval(Duration::from_secs(30));
+
+        {
+            let mut engine = engine_clone.lock().await;
+            let autos = autos_clone.lock().await;
+            let triggered = engine.check_system_event(&autos, &SystemEventType::Startup);
+            if !triggered.is_empty() {
+                let _ = trigger_tx_clone.send(triggered).await;
+            }
+        }
+
+        let _file_watch_handle = {
+            let engine_clone2 = engine_clone.clone();
+            let autos_clone2 = autos_clone.clone();
+            let trigger_tx_clone2 = trigger_tx.clone();
+
+            tokio::spawn(async move {
+                loop {
+                    let paths = {
+                        let engine = engine_clone2.lock().await;
+                        engine.get_file_watch_paths()
+                    };
+
+                    if paths.is_empty() {
+                        tokio::time::sleep(Duration::from_secs(5)).await;
+                        continue;
+                    }
+
+                    let (tx, mut rx) = tokio::sync::mpsc::channel(100);
+                    let watcher = notify::recommended_watcher(move |res: Result<notify::Event, notify::Error>| {
+                        if let Ok(event) = res {
+                            if matches!(event.kind, EventKind::Modify(_) | EventKind::Create(_) | EventKind::Remove(_)) {
+                                for path in event.paths {
+                                    let _ = tx.try_send(path.to_string_lossy().to_string());
+                                }
+                            }
+                        }
+                    });
+
+                    if let Ok(mut watcher) = watcher {
+                        for path in &paths {
+                            if path.exists() {
+                                let _ = watcher.watch(path, RecursiveMode::Recursive);
+                            }
+                        }
+
+                        while let Some(path) = rx.recv().await {
+                            let engine = engine_clone2.lock().await;
+                            let autos = autos_clone2.lock().await;
+                            let triggered = engine.check_file_event(&autos, &path);
+                            if !triggered.is_empty() {
+                                let _ = trigger_tx_clone2.send(triggered).await;
+                            }
+                        }
+                    } else {
+                        tokio::time::sleep(Duration::from_secs(5)).await;
+                    }
+                }
+            })
+        };
+
+        let _notification_handle = {
+            let engine_clone3 = engine_clone.clone();
+            let autos_clone3 = autos_clone.clone();
+            let trigger_tx_clone3 = trigger_tx.clone();
+
+            tokio::spawn(async move {
+                let _ = triggers::listen_notifications(
+                    autos_clone3,
+                    engine_clone3,
+                    trigger_tx_clone3,
+                ).await;
+            })
+        };
+
+        loop {
+            tokio::select! {
+                _ = battery_interval.tick() => {
+                    if let Some((pct, charging)) = read_battery() {
+                        let mut engine = engine_clone.lock().await;
+                        let autos = autos_clone.lock().await;
+                        let triggered = engine.check_battery_trigger(&autos, pct, charging);
+                        if !triggered.is_empty() {
+                            let _ = trigger_tx_clone.send(triggered).await;
+                        }
+                    }
+                }
+                _ = cron_interval.tick() => {
+                    let mut engine = engine_clone.lock().await;
+                    let autos = autos_clone.lock().await;
+                    let triggered = engine.check_cron_triggers(&autos);
+                    if !triggered.is_empty() {
+                        let _ = trigger_tx_clone.send(triggered).await;
+                    }
+                }
+                _ = idle_check_interval.tick() => {
+                    let mut engine = engine_clone.lock().await;
+                    let autos = autos_clone.lock().await;
+                    let triggered = engine.check_system_event(&autos, &SystemEventType::Idle { timeout_seconds: 300 });
+                    if !triggered.is_empty() {
+                        let _ = trigger_tx_clone.send(triggered).await;
+                    }
+                }
+            }
+        }
+    });
+
+    let mut app = App::new(storage);
+
+    if let Some(battery) = read_battery() {
+        app.battery_info = Some(battery);
+    }
+
+    {
+        let mut engine = engine_arc.lock().await;
+        let autos = automations_arc.lock().await;
+        engine.index_automations(&autos);
+        app.auto_trigger_count = autos.iter().filter(|a| a.has_auto_trigger()).count();
+    }
+
+    setup_terminal()?;
+
+    let result = run_app(&mut app, &mut trigger_rx, &automations_arc, &engine_arc).await;
+
+    restore_terminal()?;
+
+    if let Err(e) = result {
+        eprintln!("Error: {}", e);
+        std::process::exit(1);
+    }
+
+    Ok(())
+}
+
+fn setup_terminal() -> Result<()> {
+    enable_raw_mode()?;
+    io::stdout().execute(EnterAlternateScreen)?;
+    Ok(())
+}
+
+fn restore_terminal() -> Result<()> {
+    disable_raw_mode()?;
+    io::stdout().execute(LeaveAlternateScreen)?;
+    Ok(())
+}
