+use serde::{Deserialize, Serialize};
+use chrono::{DateTime, Utc};
+use uuid::Uuid;
+
+#[derive(Debug, Clone, Serialize, Deserialize)]
+pub struct Automation {
+    pub id: String,
+    pub name: String,
+    pub description: String,
+    pub commands: Vec<Command>,
+    pub triggers: Vec<Trigger>,
+    pub created_at: DateTime<Utc>,
+    pub last_run: Option<DateTime<Utc>>,
+    pub enabled: bool,
+}
+
+#[derive(Debug, Clone, Serialize, Deserialize)]
+pub struct Command {
+    pub name: String,
+    pub command: String,
+    pub args: Vec<String>,
+    pub working_dir: Option<String>,
+}
+
+#[derive(Debug, Clone, Serialize, Deserialize)]
+#[serde(tag = "type", rename_all = "snake_case")]
+pub enum Trigger {
+    Manual,
+    Cron {
+        expression: String,
+    },
+    FileWatch {
+        paths: Vec<String>,
+        recursive: bool,
+    },
+    Battery {
+        condition: BatteryCondition,
+        threshold: Option<u8>,
+        charging: Option<bool>,
+    },
+    Notification {
+        app_name: Option<String>,
+        contains_text: Option<String>,
+    },
+    SystemEvent {
+        event: SystemEventType,
+    },
+}
+
+#[derive(Debug, Clone, Serialize, Deserialize)]
+#[serde(rename_all = "snake_case")]
+pub enum BatteryCondition {
+    Below,
+    Above,
+    Full,
+    Low,
+    Charging,
+    Discharging,
+}
+
+#[derive(Debug, Clone, Serialize, Deserialize)]
+#[serde(rename_all = "snake_case")]
+pub enum SystemEventType {
+    Startup,
+    Idle { timeout_seconds: u64 },
+    Lock,
+    Unlock,
+}
+
+impl Automation {
+    pub fn new(name: String, description: String) -> Self {
+        Self {
+            id: Uuid::new_v4().to_string(),
+            name,
+            description,
+            commands: Vec::new(),
+            triggers: vec![Trigger::Manual],
+            created_at: Utc::now(),
+            last_run: None,
+            enabled: true,
+        }
+    }
+
+    pub fn filename(&self) -> String {
+        format!("{}.yaml", self.id)
+    }
+
+    pub fn has_auto_trigger(&self) -> bool {
+        self.triggers.iter().any(|t| !matches!(t, Trigger::Manual))
+    }
+}
+
+impl Trigger {
+    pub fn label(&self) -> String {
+        match self {
+            Trigger::Manual => "Manual".to_string(),
+            Trigger::Cron { expression } => format!("Cron: {}", expression),
+            Trigger::FileWatch { paths, recursive } => {
+                let rec = if *recursive { " (recursive)" } else { "" };
+                format!("Watch: {}{}", paths.join(", "), rec)
+            }
+            Trigger::Battery { condition, threshold, charging } => {
+                let mut s = "Battery: ".to_string();
+                match condition {
+                    BatteryCondition::Below => s.push_str(&format!("below {}%", threshold.unwrap_or(20))),
+                    BatteryCondition::Above => s.push_str(&format!("above {}%", threshold.unwrap_or(80))),
+                    BatteryCondition::Full => s.push_str("full"),
+                    BatteryCondition::Low => s.push_str("low (<20%)"),
+                    BatteryCondition::Charging => s.push_str("charging"),
+                    BatteryCondition::Discharging => s.push_str("discharging"),
+                }
+                if let Some(c) = charging {
+                    s.push_str(&format!(" (charging={})", c));
+                }
+                s
+            }
+            Trigger::Notification { app_name, contains_text } => {
+                let mut s = "Notification".to_string();
+                if let Some(app) = app_name {
+                    s.push_str(&format!(" from: {}", app));
+                }
+                if let Some(text) = contains_text {
+                    s.push_str(&format!(" contains: \"{}\"", text));
+                }
+                s
+            }
+            Trigger::SystemEvent { event } => match event {
+                SystemEventType::Startup => "System: Startup".to_string(),
+                SystemEventType::Idle { timeout_seconds } => format!("System: Idle ({}s)", timeout_seconds),
+                SystemEventType::Lock => "System: Lock".to_string(),
+                SystemEventType::Unlock => "System: Unlock".to_string(),
+            },
+        }
+    }
+}

