+            .unwrap_or_else(|| PathBuf::from("./automations"));
+
+        fs::create_dir_all(&data_dir)?;
+
+        Ok(Self { data_dir })
+    }
+
+    pub fn list_automations(&self) -> Result<Vec<Automation>> {
+        let mut automations = Vec::new();
+
+        if !self.data_dir.exists() {
+            return Ok(automations);
+        }
+
+        for entry in fs::read_dir(&self.data_dir)? {
+            let entry = entry?;
+            let path = entry.path();
+
+            if path.extension().and_then(|e| e.to_str()) == Some("yaml") {
+                let content = fs::read_to_string(&path)?;
+                let automation: Automation = serde_yaml::from_str(&content)
+                    .with_context(|| format!("Failed to parse {}", path.display()))?;
+                automations.push(automation);
+            }
+        }
+
+        automations.sort_by(|a, b| a.name.cmp(&b.name));
+        Ok(automations)
+    }
+
+    pub fn save_automation(&self, automation: &Automation) -> Result<()> {
+        let path = self.data_dir.join(automation.filename());
+        let content = serde_yaml::to_string(automation)?;
+        fs::write(&path, content)?;
+        Ok(())
+    }
+
+    pub fn delete_automation(&self, id: &str) -> Result<()> {
+        let path = self.data_dir.join(format!("{}.yaml", id));
+        if path.exists() {
+            fs::remove_file(&path)?;
+        }
+        Ok(())
+    }
+
+    pub fn get_automation(&self, id: &str) -> Result<Option<Automation>> {
+        let path = self.data_dir.join(format!("{}.yaml", id));
+        if path.exists() {
+            let content = fs::read_to_string(&path)?;
+            let automation: Automation = serde_yaml::from_str(&content)?;
+            Ok(Some(automation))
+        } else {
+            Ok(None)
+        }
+    }
+
+    pub fn get_file_path(&self, id: &str) -> PathBuf {
+        self.data_dir.join(format!("{}.yaml", id))
+    }
