+use std::collections::HashMap;
+use std::fs;
+use std::path::PathBuf;
+use std::sync::Arc;
+use std::time::{Duration, Instant};
+use chrono::Utc;
+use cron::Schedule;
+use tokio::sync::Mutex;
+use anyhow::Result;
+
+use crate::model::{Automation, Trigger, BatteryCondition, SystemEventType};
+
+#[derive(Debug, Clone)]
+pub enum TriggerEvent {
+    Cron(String),
+    FileChange(String),
+    BatteryState { percent: u8, charging: bool },
+    Notification { app_name: String, summary: String, body: String },
+    SystemStartup,
+    SystemIdle,
+    SystemLock,
+    SystemUnlock,
+}
+
+pub struct TriggerEngine {
+    cron_schedules: HashMap<String, Vec<(Schedule, Option<chrono::DateTime<Utc>>)>>,
+    file_watch_paths: HashMap<String, Vec<PathBuf>>,
+    last_battery_state: Option<(u8, bool)>,
+    battery_cooldown: Option<Instant>,
+    last_idle_activity: Instant,
+    startup_triggered: bool,
+}
+
+impl TriggerEngine {
+    pub fn new() -> Self {
+        Self {
+            cron_schedules: HashMap::new(),
+            file_watch_paths: HashMap::new(),
+            last_battery_state: None,
+            battery_cooldown: None,
+            last_idle_activity: Instant::now(),
+            startup_triggered: false,
+        }
+    }
+
+    pub fn index_automations(&mut self, automations: &[Automation]) {
+        self.cron_schedules.clear();
+        self.file_watch_paths.clear();
+
+        for auto in automations {
+            if !auto.enabled {
+                continue;
+            }
+
+            for trigger in &auto.triggers {
+                match trigger {
+                    Trigger::Cron { expression } => {
+                        if let Ok(schedule) = expression.parse::<Schedule>() {
+                            self.cron_schedules
+                                .entry(auto.id.clone())
+                                .or_default()
+                                .push((schedule, None));
+                        }
+                    }
+                    Trigger::FileWatch { paths, .. } => {
+                        let pathbufs: Vec<PathBuf> = paths.iter().map(PathBuf::from).collect();
+                        self.file_watch_paths
+                            .entry(auto.id.clone())
+                            .or_default()
+                            .extend(pathbufs);
+                    }
+                    _ => {}
+                }
+            }
+        }
+    }
+
+    pub fn check_cron_triggers(&mut self, automations: &[Automation]) -> Vec<String> {
+        let now = Utc::now();
+        let mut triggered = Vec::new();
+
+        for auto in automations {
+            if !auto.enabled {
+                continue;
+            }
+
+            if let Some(entries) = self.cron_schedules.get_mut(&auto.id) {
+                for (schedule, last_triggered) in entries {
+                    if let Some(next_time) = schedule.after(&now).next() {
+                        let should_trigger = match last_triggered {
+                            Some(last) => next_time > *last,
+                            None => true,
+                        };
+
+                        if should_trigger {
+                            let diff = next_time - now;
+                            if diff.num_seconds() <= 60 {
+                                triggered.push(auto.id.clone());
+                                *last_triggered = Some(next_time);
+                                break;
+                            }
+                        }
+                    }
+                }
+            }
+        }
+
+        triggered
+    }
+
+    pub fn check_battery_trigger(
+        &mut self,
+        automations: &[Automation],
+        percent: u8,
+        charging: bool,
+    ) -> Vec<String> {
+        let now = Instant::now();
+        if let Some(cooldown) = self.battery_cooldown {
+            if now.duration_since(cooldown) < Duration::from_secs(30) {
+                return Vec::new();
+            }
+        }
+
+        let prev = self.last_battery_state;
+        self.last_battery_state = Some((percent, charging));
+
+        let mut triggered = Vec::new();
+
+        for auto in automations {
+            if !auto.enabled {
+                continue;
+            }
+
+            for trigger in &auto.triggers {
+                if let Trigger::Battery { condition, threshold, charging: trigger_charging } = trigger {
+                    let matches = match condition {
+                        BatteryCondition::Below => {
+                            let thresh = threshold.unwrap_or(20);
+                            percent < thresh
+                        }
+                        BatteryCondition::Above => {
+                            let thresh = threshold.unwrap_or(80);
+                            percent > thresh
+                        }
+                        BatteryCondition::Full => percent >= 95,
+                        BatteryCondition::Low => percent < 20,
+                        BatteryCondition::Charging => charging,
+                        BatteryCondition::Discharging => !charging,
+                    };
+
+                    let charging_match = match trigger_charging {
+                        Some(tc) => *tc == charging,
+                        None => true,
+                    };
+
+                    if matches && charging_match {
+                        if let Some((prev_pct, prev_chg)) = prev {
+                            if percent != prev_pct || charging != prev_chg {
+                                triggered.push(auto.id.clone());
+                                self.battery_cooldown = Some(now);
+                                break;
+                            }
+                        } else {
+                            triggered.push(auto.id.clone());
+                            self.battery_cooldown = Some(now);
+                            break;
+                        }
+                    }
+                }
+            }
+        }
+
+        triggered
+    }
+
+    pub fn check_notification_trigger(
+        &self,
+        automations: &[Automation],
+        app_name: &str,
+        summary: &str,
+        body: &str,
+    ) -> Vec<String> {
+        let mut triggered = Vec::new();
+
+        for auto in automations {
+            if !auto.enabled {
+                continue;
+            }
+
+            for trigger in &auto.triggers {
+                if let Trigger::Notification { app_name: trigger_app, contains_text } = trigger {
+                    let app_match = match trigger_app {
+                        Some(ta) => app_name.to_lowercase().contains(&ta.to_lowercase()),
+                        None => true,
+                    };
+
+                    let text_match = match contains_text {
+                        Some(ct) => {
+                            summary.to_lowercase().contains(&ct.to_lowercase())
+                                || body.to_lowercase().contains(&ct.to_lowercase())
+                        }
+                        None => true,
+                    };
+
+                    if app_match && text_match {
+                        triggered.push(auto.id.clone());
+                        break;
+                    }
+                }
+            }
+        }
+
+        triggered
+    }
+
+    pub fn check_system_event(
+        &mut self,
+        automations: &[Automation],
+        event: &SystemEventType,
+    ) -> Vec<String> {
+        let mut triggered = Vec::new();
+
+        match event {
+            SystemEventType::Startup => {
+                if self.startup_triggered {
+                    return Vec::new();
+                }
+                self.startup_triggered = true;
+            }
+            SystemEventType::Idle { timeout_seconds } => {
+                let elapsed = self.last_idle_activity.elapsed().as_secs();
+                if elapsed < *timeout_seconds {
+                    return Vec::new();
+                }
+            }
+            _ => {}
+        }
+
+        for auto in automations {
+            if !auto.enabled {
+                continue;
+            }
+
+            for trigger in &auto.triggers {
+                if let Trigger::SystemEvent { event: trigger_event } = trigger {
+                    let matches = match (event, trigger_event) {
+                        (SystemEventType::Startup, SystemEventType::Startup) => true,
+                        (SystemEventType::Idle { .. }, SystemEventType::Idle { .. }) => true,
+                        (SystemEventType::Lock, SystemEventType::Lock) => true,
+                        (SystemEventType::Unlock, SystemEventType::Unlock) => true,
+                        _ => false,
+                    };
+
+                    if matches {
+                        triggered.push(auto.id.clone());
+                        break;
+                    }
+                }
+            }
+        }
+
+        triggered
+    }
+
+    pub fn record_activity(&mut self) {
+        self.last_idle_activity = Instant::now();
+    }
+
+    pub fn get_file_watch_paths(&self) -> Vec<PathBuf> {
+        self.file_watch_paths.values().flatten().cloned().collect()
+    }
+
+    pub fn check_file_event(&self, automations: &[Automation], path: &str) -> Vec<String> {
+        let mut triggered = Vec::new();
+
+        for auto in automations {
+            if !auto.enabled {
+                continue;
+            }
+
+            for trigger in &auto.triggers {
+                if let Trigger::FileWatch { paths, recursive } = trigger {
+                    let path_match = paths.iter().any(|watched| {
+                        if *recursive {
+                            path.starts_with(watched.as_str())
+                        } else {
+                            path == watched.as_str()
+                        }
+                    });
+
+                    if path_match {
+                        triggered.push(auto.id.clone());
+                        break;
+                    }
+                }
+            }
+        }
+
+        triggered
+    }
+}
+
+pub fn read_battery() -> Option<(u8, bool)> {
+    for entry in fs::read_dir("/sys/class/power_supply").ok()? {
+        let entry = entry.ok()?;
+        let path = entry.path();
+
+        let typ_path = path.join("type");
+        if let Ok(typ) = fs::read_to_string(&typ_path) {
+            if typ.trim() == "Battery" {
+                let capacity = fs::read_to_string(path.join("capacity")).ok()?;
+                let status = fs::read_to_string(path.join("status")).ok()?;
+
+                let percent: u8 = capacity.trim().parse().ok()?;
+                let charging = status.trim() == "Charging" || status.trim() == "Full";
+
+                return Some((percent, charging));
+            }
+        }
+    }
+    None
+}
+
+#[zbus::proxy(
+    interface = "org.freedesktop.Notifications",
+    default_service = "org.freedesktop.Notifications",
+    default_path = "/org/freedesktop/Notifications"
+)]
+trait Notifications {
+    #[zbus(signal)]
+    fn notification(
+        &self,
+        app_name: String,
+        id: u32,
+        app_icon: String,
+        summary: String,
+        body: String,
+        actions: Vec<String>,
+        hints: std::collections::HashMap<String, zbus::zvariant::Value<'_>>,
+        expire_timeout: i32,
+    ) -> zbus::Result<()>;
+}
+
+pub async fn listen_notifications(
+    automations: Arc<Mutex<Vec<Automation>>>,
+    engine: Arc<Mutex<TriggerEngine>>,
+    tx: tokio::sync::mpsc::Sender<Vec<String>>,
+) -> Result<()> {
+    use futures::StreamExt;
+
+    loop {
+        let conn = match zbus::Connection::session().await {
+            Ok(c) => c,
+            Err(_) => {
+                tokio::time::sleep(Duration::from_secs(10)).await;
+                continue;
+            }
+        };
+
+        let proxy = match NotificationsProxy::new(&conn).await {
+            Ok(p) => p,
+            Err(_) => {
+                tokio::time::sleep(Duration::from_secs(10)).await;
+                continue;
+            }
+        };
+
+        let mut signal_stream = match proxy.receive_notification().await {
+            Ok(s) => s,
+            Err(_) => {
+                tokio::time::sleep(Duration::from_secs(10)).await;
+                continue;
+            }
+        };
+
+        while let Some(signal) = signal_stream.next().await {
+            let args = match signal.args() {
+                Ok(a) => a,
+                Err(_) => continue,
+            };
+
+            let triggered = {
+                let autos = automations.lock().await;
+                let eng = engine.lock().await;
+                eng.check_notification_trigger(&autos, &args.app_name, &args.summary, &args.body)
+            };
+
+            if !triggered.is_empty() {
+                let _ = tx.send(triggered).await;
+            }
+        }
+
+        tokio::time::sleep(Duration::from_secs(5)).await;
+    }
+}

