+    pub battery_info: Option<(u8, bool)>,
+    pub auto_trigger_count: usize,
+}
+
+impl App {
+    pub fn new(storage: Storage) -> Self {
+        let automations = storage.list_automations().unwrap_or_default();
+        let mut list_state = ListState::default();
+        if !automations.is_empty() {
+            list_state.select(Some(0));
+        }
+        Self {
+            storage,
+            automations,
+            list_state,
+            view: AppView::List,
+            create_name: String::new(),
+            create_description: String::new(),
+            create_field: CreateField::Name,
+            running_output: String::new(),
+            running: false,
+            error: None,
+            show_help: false,
+            battery_info: None,
+            auto_trigger_count: 0,
+        }
+    }
+
+    pub fn refresh(&mut self) {
+        let prev_selected = self.list_state.selected().unwrap_or(0);
+        self.automations = self.storage.list_automations().unwrap_or_default();
+        let new_len = self.automations.len();
+        if new_len == 0 {
+            self.list_state.select(None);
+        } else {
+            let new_selected = if prev_selected >= new_len { new_len - 1 } else { prev_selected };
+            self.list_state.select(Some(new_selected));
+        }
+    }
+
+    pub fn selected_automation(&self) -> Option<&Automation> {
+        self.list_state.selected().and_then(|i| self.automations.get(i))
+    }
+
+    pub fn selected_index(&self) -> Option<usize> {
+        self.list_state.selected()
+    }
