+fn render_create(frame: &mut Frame, app: &App, area: Rect) {
+    let name_style = if app.create_field == CreateField::Name {
+        Style::default().fg(Color::Yellow)
+    } else {
+        Style::default()
+    };
+
+    let desc_style = if app.create_field == CreateField::Description {
+        Style::default().fg(Color::Yellow)
+    } else {
+        Style::default()
+    };
+
+    let cursor_pos = if app.create_field == CreateField::Name {
+        (4 + app.create_name.len() as u16, 2)
+    } else {
+        (4 + app.create_description.len() as u16, 5)
+    };
+
+    let lines = vec![
+        Line::from(Span::styled("Name: ", Style::default().fg(Color::Cyan))),
+        Line::from(vec![
